const cb = document.querySelector('input[type=checkbox]');
let info = {found_cb: !!cb};
if (cb) { cb.checked = true; cb.dispatchEvent(new Event('change',{bubbles:true})); cb.dispatchEvent(new Event('click',{bubbles:true})); }
// find Enter button
const btns = [...document.querySelectorAll('button, input[type=button], .macro-button, a')].filter(b=>/^\s*Enter\s*$/i.test(b.textContent||b.value||''));
info.enter_btns = btns.length;
if (btns.length) { btns[btns.length-1].click(); }
return JSON.stringify(info);
